        for clause in clauses:
            index = 0
            for var in clause:
                if var > 0:
                    index |= 1 << (var - 1)
                else:
                    index &= ~(1 << (-var - 1))
            poly[index][index] += 1
        return poly

    def schur_weyl_representation(poly):
        n = int(math.log2(len(poly)))
        rep = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(2 ** n):
            for j in range(2 ** n):
                if poly[i][j] > 0:
                    rep[i & j][i | j] += poly[i][j]
        return rep

    def min_rank(rep):
        m = len(rep)
        n = len(rep[0])
        rank = 0
        for i in range(m):
            pivot = None
            for j in range(n):
