                product = 1
                for k in range(n):
                    if clauses[k][i & (1 << k)] == -clauses[k][j & (1 << k)]:
                        product *= -1
                poly[i][j] = product
        return poly

    def min_rank(matrix):
        m, n = len(matrix), len(matrix[0])
        rank = 0
        for i in range(m):
            if any(matrix[j][i] != 0 for j in range(i, m)):
                rank += 1
                for j in range(n):
