                        factor = Fraction(matrix[k][i], matrix[i][i])
                        for j in range(n):
                            matrix[k][j] -= factor * matrix[i][j]
        return rank

    def dpll_length(clauses):
        stack = []
        assignment = [None] * len(clauses[0])

        def backtrack():
            while stack:
                i, val = stack.pop()
                if val == 1:
                    assignment[i] = -1
                else:
                    assignment[i] = 1
                for j in range(len(clauses)):
